import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_roots_mod_p(f, p):
    # Compute the polynomial f(x) mod p
    f_mod_p = f.subs(sympy.symbols('x'), sympy.mod(f, p))
    # Check if f_mod_p has roots mod p
    return sympy.solve(f_mod_p, sympy.symbols('x'))!= []

